'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Field, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './field.css'
// The shared rule sets. A checkbox and a radio are pressed, so they carry the
// press gesture, and a theme that changes that gesture reaches them through the
// class rather than through a line each component has to remember (GSUI-118).
import '../../../tokens/primitives.css'
import { CrossGlyph, TickGlyph } from './glyphs'

/**
 * Field: one thing a player types or ticks, with its label and its reason.
 *
 * BDS-040 is the whole of the visual rule: inputs are inset, controls are
 * raised. A text field carries `data-gs-elevation="inset"`, a checkbox and a
 * radio carry `raised`, and that single difference is how a player tells what
 * they type into from what they press. It is why `field` and `button` are not
 * the same base component.
 *
 * It performs nothing. It validates nothing, decides nothing, and stores
 * nothing. `invalid` is the host's word that the value failed, `valid` is the
 * host's word that it passed, and `reason` is the host's sentence saying why;
 * a field that judged its own value would be a second validator disagreeing
 * with the host's.
 *
 * Required and optional are words on screen, not a colour and not an asterisk.
 * `aria-required` carries the same fact to a screen reader, so the state is
 * never left to the sighted reading of a punctuation mark.
 */

/**
 * What the player does to it. The first five are typed into and read as inset;
 * the last two are pressed and read as raised.
 *
 * `select` is not here: one value out of a known set is `selector`, whose
 * dropdown presentation is that control, and a second one would be a second
 * accessibility story for the same act.
 */
export type FieldControl = 'text' | 'email' | 'tel' | 'password' | 'number' | 'checkbox' | 'radio'

/** Whether the player has to fill this in. Rendered as a word, both ways. */
export type FieldRequirement = 'required' | 'optional'

const PRESSED: ReadonlySet<FieldControl> = new Set<FieldControl>(['checkbox', 'radio'])

/** The words that go with the two requirements, fixed here rather than per host. */
const REQUIREMENT_WORD: Record<FieldRequirement, string> = {
  required: 'Required.',
  optional: 'Optional.',
}

/** What the password reveal says, in the two states it has. */
const REVEAL_WORD = { hidden: 'Show', shown: 'Hide' } as const

export interface FieldProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'type' | 'name' | 'required'> {
  /** Which field this is. Rides `data-gs-field` and names the value on submit. */
  name: string
  /** What the player is being asked for. Always rendered, never a placeholder. */
  label: React.ReactNode
  /** What the player does to it. Decides inset against raised. */
  control?: FieldControl
  /**
   * Whether the player has to fill this in, said in words beside the label.
   * `required` also sets `aria-required`, so the fact reaches a screen reader.
   */
  requirement?: FieldRequirement
  /** A supporting line under the field. Never the only place a rule is stated. */
  help?: React.ReactNode
  /**
   * Why the value failed, or what passing it did, in the host's own words.
   * Rendered under the field and attached to the control with
   * `aria-describedby`, so it is announced rather than only seen.
   */
  reason?: React.ReactNode
  /** The host's word that the value failed. The component never decides it. */
  invalid?: boolean
  /**
   * The host's word that the value passed: a team code that joined a team, an
   * email that was recognised. The stroke goes positive and a tick disc appears
   * where the cross would. The component never decides it, and `invalid` wins
   * if a host sets both.
   */
  valid?: boolean
}



export function Field({
  name,
  label,
  control = 'text',
  requirement,
  help,
  reason,
  invalid = false,
  valid = false,
  disabled = false,
  className,
  id,
  ...rest
}: FieldProps) {
  // One id per field, so the label points at the control and the reason is
  // announced with it. useId rather than a counter: two fields with the same
  // name on one page is a legitimate thing a host does.
  const generated = React.useId()
  const controlId = id ?? `${generated}-control`
  const reasonId = `${generated}-reason`
  const helpId = `${generated}-help`

  // Whether a password is on show. Held here, in memory, for as long as the
  // field is on screen: it is a fact about the screen and not about the value,
  // so the host is never asked to carry it.
  const [revealed, setRevealed] = React.useState(false)

  const pressed = PRESSED.has(control)
  const passed = valid && !invalid
  const describedBy =
    [reason ? reasonId : null, help ? helpId : null].filter(Boolean).join(' ') || undefined

  const input = (
    <input
      {...rest}
      id={controlId}
      name={name}
      type={control === 'password' && revealed ? 'text' : control}
      disabled={disabled}
      required={requirement === 'required'}
      aria-required={requirement === 'required' || undefined}
      aria-invalid={invalid || undefined}
      aria-describedby={describedBy}
      className="gs-field__control"
      data-gs-scope="field"
      data-gs-part="control"
      // The rule a player reads without being told it: typed into, or pressed.
      data-gs-elevation={pressed ? 'raised' : 'inset'}
    />
  )

  const labelText = (
    <label className="gs-field__label" htmlFor={controlId}>
      {label}
      {requirement ? (
        // The word, not a star. "Required." after the label is the thing the
        // design asks for and the thing a translator can translate.
        <span className="gs-field__requirement" data-gs-scope="field" data-gs-part="requirement">
          {REQUIREMENT_WORD[requirement]}
        </span>
      ) : null}
    </label>
  )

  return (
    <div
      className={['gs-field', className].filter(Boolean).join(' ')}
      data-gs-component="field"
      data-gs-field={name}
      data-gs-invalid={invalid ? 'true' : undefined}
      data-gs-valid={passed ? 'true' : undefined}
      data-gs-disabled={disabled ? 'true' : undefined}
    >
      {pressed ? (
        // Tick first, then the sentence, because the sentence is often long
        // enough to wrap and the box has to stay where the thumb expects it.
        <div className="gs-field__tickrow">
          <span className="gs-field__box gs-pressable">
            {input}
            {/* A checkbox gets a tick and a radio gets a dot, because that is
                what each one means: several things ticked, or one of a set
                chosen. Both are a change of shape and not only of fill. */}
            <span className="gs-field__tick" aria-hidden="true">
              {control === 'checkbox' ? <TickGlyph /> : null}
            </span>
          </span>
          {labelText}
        </div>
      ) : (
        <>
          {labelText}
          <div className="gs-field__row">
            {input}
            {invalid || passed ? (
              // The disc that carries the verdict without colour: a cross for
              // failed, a tick for passed. Specimen 4b draws both.
              <span
                className="gs-field__glyph"
                data-gs-scope="field"
                data-gs-part="glyph"
                data-gs-animates="emphasis"
                aria-hidden="true"
              >
                {invalid ? <CrossGlyph /> : <TickGlyph />}
              </span>
            ) : null}
            {control === 'password' ? (
              // A word, not an eye: "Show" says what pressing it does, and the
              // pressed state says what it did. aria-controls ties it to the
              // field it reveals, so a screen reader hears which one.
              <button
                type="button"
                className="gs-field__reveal gs-pressable"
                data-gs-scope="field"
                data-gs-part="reveal"
                aria-pressed={revealed}
                aria-controls={controlId}
                aria-label={revealed ? 'Hide password' : 'Show password'}
                disabled={disabled}
                onClick={() => setRevealed((was) => !was)}
              >
                {revealed ? REVEAL_WORD.shown : REVEAL_WORD.hidden}
              </button>
            ) : null}
          </div>
        </>
      )}

      {reason ? (
        <p className="gs-field__reason" id={reasonId} data-gs-scope="field" data-gs-part="reason">
          {reason}
        </p>
      ) : null}
      {help ? (
        <p className="gs-field__help" id={helpId} data-gs-scope="field" data-gs-part="help">
          {help}
        </p>
      ) : null}
    </div>
  )
}

/* Field. Every value comes from a token; nothing here is a literal colour.

   Specimen 4b draws this component and design/twins/4b.json measures ours
   against it, part by part: the text field idle, focused, failed and passed,
   its label, its reason line, the password reveal, the checkbox and the radio.
   Where a value below is not what the drawing draws, the twins file says so
   and why, and the token requests are in the report that shipped with it. */

.gs-field {
  display: flex;
  flex-direction: column;
  /* The drawing puts 8px under the label and 6px over the reason. One gap. */
  gap: var(--gs-space-2);
  font-family: var(--gs-type-body-font-family);
  color: var(--gs-color-ink);
  min-inline-size: 0;
}

/* -- label ----------------------------------------------------------------- */
/* The label type, whole: family, size, weight, tracking and case. The drawing
   types every field label in capitals, and arcade's label token carries that
   as a transform so the theme decides it rather than the host's copy. */
.gs-field__label {
  display: flex;
  flex-wrap: wrap;
  gap: var(--gs-space-2);
  align-items: baseline;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  text-transform: var(--gs-type-label-text-transform, none);
  color: var(--gs-color-ink-secondary);
}

/* The label takes the verdict's colour with the stroke and the disc, so the
   three of them read as one state and not as a red box under a grey word. */
.gs-field[data-gs-invalid='true'] .gs-field__label { color: var(--gs-color-negative-solid); }
.gs-field[data-gs-valid='true'] .gs-field__label { color: var(--gs-color-positive-solid); }

/* "Required." and "Optional." sit beside the label as words. They are quieter
   than the label and never the only carrier of the fact: aria-required says the
   same thing to a screen reader. */
.gs-field__requirement {
  color: var(--gs-color-muted);
}

/* -- the control ----------------------------------------------------------- */
/* BDS-040. Inset: the surface recedes and carries no depth, so it reads as a
   hole you type into beside a control that stands up. The drawing carries the
   recess as a 3px quarter-black inset shadow on every one of
   its six text fields; there is no inset depth token yet, so ours is flat and
   the difference is on record in the twins file. */
.gs-field__row {
  position: relative;
  display: flex;
  align-items: center;
}

.gs-field__control[data-gs-elevation='inset'] {
  inline-size: 100%;
  /* The drawing's field is 56px, which is size.action in the base theme and
     4px under it in arcade. No token is nearer; see the report. */
  min-block-size: var(--gs-size-action);
  box-sizing: border-box;
  padding: 0 var(--gs-space-4);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-control) solid var(--gs-color-edge);
  /* The control radius, 16px: the drawing draws every field at it. */
  border-radius: var(--gs-radius-control);
  box-shadow: var(--gs-depth-flat);
  color: var(--gs-color-ink);

  /* 16px is the floor: below it iOS zooms the page on focus, which throws the
     player out of the layout they were looking at. */
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);

  transition: border-color var(--gs-motion-emphasis) ease-out;
}

.gs-field__control::placeholder {
  color: var(--gs-color-muted);
}

/* Focus is the stroke turning to the selected colour and nothing else. The
   drawing draws no ring: a 3px stroke changing from the darkest colour on the
   surface to the brightest is the indicator, and a ring on top of it made the
   field the loudest thing on the screen while it was being typed into. */
.gs-field__control[data-gs-elevation='inset']:focus-visible {
  outline: none;
  border-color: var(--gs-color-selected);
}

/* The verdict changes the stroke, the pattern and the glyph together, never
   the colour alone: dashed against solid survives any colour vision, and the
   reason below says it in words. Passed is the same three changes the other
   way: solid, positive, tick. */
.gs-field[data-gs-invalid='true'] .gs-field__control[data-gs-elevation='inset'] {
  border-style: dashed;
  border-color: var(--gs-color-negative-solid);
}

.gs-field[data-gs-valid='true'] .gs-field__control[data-gs-elevation='inset'] {
  border-color: var(--gs-color-positive-solid);
}

/* Room for the disc at the end of the value. The drawing draws the disc as a
   flex child of the box; an <input> cannot hold a child, so the disc sits over
   the input's own end padding instead. Same picture, different padding, and
   the twins file allows that one property for that reason. */
.gs-field[data-gs-invalid='true'] .gs-field__control[data-gs-elevation='inset'],
.gs-field[data-gs-valid='true'] .gs-field__control[data-gs-elevation='inset'] {
  padding-inline-end: var(--gs-space-12);
}

/* The status disc: a 22px circle in the drawing, ringed in the edge colour,
   filled with the verdict, the mark inside it. icon-control is 24 and the
   nearest token. The mark is drawn at the label size, which is what keeps a
   9px cross from greying out into its own antialiasing. */
.gs-field__glyph {
  position: absolute;
  inset-inline-end: var(--gs-space-3);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--gs-size-icon-control);
  block-size: var(--gs-size-icon-control);
  box-sizing: border-box;
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-negative);
  color: var(--gs-color-on-bright);
  font-size: var(--gs-type-label-font-size);
  pointer-events: none;
}

.gs-field[data-gs-valid='true'] .gs-field__glyph {
  background: var(--gs-color-positive);
}

/* -- password reveal ------------------------------------------------------- */
/* A small raised control inside the field's end: the drawing's "Show" is 40px
   tall, padded 12, on the edge colour, in the label type. The field pads its
   end by 80px to make room for it, which is the drawing's own number. */
.gs-field__row:has(.gs-field__reveal) .gs-field__control[data-gs-elevation='inset'] {
  padding-inline-end: calc(var(--gs-space-12) + var(--gs-space-8));
}

.gs-field__reveal {
  position: absolute;
  inset-inline-end: var(--gs-space-2);
  block-size: var(--gs-size-control-small);
  padding: 0 var(--gs-space-3);
  border: 0;
  border-radius: var(--gs-radius-sm);
  background: var(--gs-color-edge);
  color: var(--gs-color-ink-secondary);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  cursor: pointer;
}

.gs-field__reveal:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-selected);
  outline-offset: 2px;
}

/* -- checkbox and radio ---------------------------------------------------- */
/* Raised, because they are pressed. Same rule as button, from the same place. */
.gs-field__tickrow {
  display: flex;
  align-items: flex-start;
  gap: var(--gs-space-gap);
}

/* The drawing's box is 30px with a 9px corner. No token is within 2px of
   either; controlSmall at 40 with radius.sm at 12 keeps the same proportion,
   three tenths, so a checkbox stays a rounded square rather than a circle. On
   record in the twins file and the report. */
.gs-field__box {
  position: relative;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--gs-size-control-small);
  block-size: var(--gs-size-control-small);
  box-sizing: border-box;
  border-radius: var(--gs-radius-sm);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-control) solid var(--gs-color-edge);
  /* The drawing's shelf under an unticked box is `0 3px 0 edge`, a plain
     offset. depth.raised is the nearest token. */
  box-shadow: var(--gs-depth-raised);
  transition: background var(--gs-motion-emphasis) ease-out,
              box-shadow var(--gs-motion-emphasis) ease-out,
              border-color var(--gs-motion-emphasis) ease-out;
}

/* A consent sentence reads as one sentence, so "Required." runs on at the end
   of it rather than sitting on a line of its own looking like a separate rule.
   Inline rather than flex for that reason alone. */
.gs-field__tickrow .gs-field__label {
  display: block;
  padding-block-start: var(--gs-space-2);
  color: var(--gs-color-ink);
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  letter-spacing: normal;
  text-transform: none;
  line-height: var(--gs-type-body-line-height);
}

.gs-field__tickrow .gs-field__requirement {
  margin-inline-start: var(--gs-space-1);
}

.gs-field__control[data-gs-elevation='raised'] {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  margin: 0;
  opacity: 0;

  /* The whole box is the target, and the box is never smaller than a thumb. */
  min-inline-size: var(--gs-size-touch-min);
  min-block-size: var(--gs-size-touch-min);
  cursor: pointer;
}

.gs-field__box:has(.gs-field__control:focus-visible) {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

.gs-field__box:has(.gs-field__control[type='radio']) {
  border-radius: var(--gs-radius-full);
}

/* Ticked: the box fills positive and comes down off its shelf, which is what
   the drawing draws. The state is a change of fill, of depth and of glyph. */
.gs-field__box:has(.gs-field__control[type='checkbox']:checked) {
  background: var(--gs-color-positive);
  box-shadow: var(--gs-depth-flat);
}

/* Chosen: the ring turns to the selected colour and the dot appears. Selected
   rather than positive, because nothing here is right or wrong. */
.gs-field__box:has(.gs-field__control[type='radio']:checked) {
  border-color: var(--gs-color-selected);
  box-shadow: var(--gs-depth-flat);
}

/* The tick is the state. It appears rather than the box only changing fill, so
   ticked and unticked differ in shape as well as in colour. */
.gs-field__tick {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: 100%;
  block-size: 100%;
  border-radius: inherit;
  color: var(--gs-color-on-bright);
  font-size: var(--gs-type-body-font-size);
  opacity: 0;
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

.gs-field__control:checked + .gs-field__tick {
  opacity: 1;
}

/* A radio fills with a dot rather than a tick: one of a set chosen, not a thing
   agreed to. The tick element is the dot itself: the drawing's is 14px in a
   30px ring, and icon-utility at 16 is the nearest token. */
.gs-field__control[type='radio'] + .gs-field__tick {
  display: block;
  inline-size: var(--gs-size-icon-utility);
  block-size: var(--gs-size-icon-utility);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-selected);
}

/* -- reason and help ------------------------------------------------------- */
/* The line under the field, in the label's face and size. The drawing sets it
   at weight 700 where the label token is 800; there is no token between. */
.gs-field__reason,
.gs-field__help {
  margin: 0;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: var(--gs-type-body-line-height);
  overflow-wrap: anywhere;
}

.gs-field__reason {
  color: var(--gs-color-negative-solid);
}

.gs-field[data-gs-valid='true'] .gs-field__reason {
  color: var(--gs-color-positive-solid);
}

/* A reason with no verdict is a rule explained, not a failure. */
.gs-field:not([data-gs-invalid='true']):not([data-gs-valid='true']) .gs-field__reason,
.gs-field__help {
  color: var(--gs-color-ink-secondary);
}

/* -- disabled -------------------------------------------------------------- */
/* Flat and out of reach, which is the button's disabled rendering and means the
   same thing here: not available at all, as against not available yet. */
.gs-field[data-gs-disabled='true'] {
  color: var(--gs-color-disabled-ink);
}

.gs-field[data-gs-disabled='true'] .gs-field__control[data-gs-elevation='inset'],
.gs-field[data-gs-disabled='true'] .gs-field__box,
.gs-field[data-gs-disabled='true'] .gs-field__reveal {
  background: var(--gs-color-disabled);
  color: var(--gs-color-disabled-ink);
  box-shadow: var(--gs-depth-flat);
  cursor: not-allowed;
}

/* Two marks render small here: the checkbox tick and the status glyph beside
   a judged value. At that size the shared glyph weight computes to less than a
   device pixel and the mark greys out into its own antialiasing. Same drawing,
   heavier stroke. */
.gs-field__tick .gs-glyph,
.gs-field__glyph .gs-glyph {
  stroke-width: var(--gs-stroke-glyph-small);
}
